#!/usr/bin/env python3
"""Remove duplicate lines from a file while preserving original order."""

import argparse
import sys


def line_key(line: str, ignore_case: bool) -> str:
    """Return the comparison key for a line."""
    # Remove only the line ending before comparing.
    if line.endswith("\n"):
        line = line[:-1]
    if line.endswith("\r"):
        line = line[:-1]

    return line.casefold() if ignore_case else line


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(
        description="Remove duplicate lines from a file while preserving the original order."
    )
    parser.add_argument(
        "input",
        nargs="?",
        help="input file; read from stdin if omitted",
    )
    parser.add_argument(
        "-o",
        "--output",
        help="output file; default is stdout",
    )
    parser.add_argument(
        "--ignore-case",
        action="store_true",
        help="treat lines that differ only by letter case as duplicates",
    )

    args = parser.parse_args(argv)

    if args.input:
        try:
            infile = open(args.input, "r", encoding="utf-8")
        except OSError as exc:
            print(f"error: cannot open {args.input}: {exc}", file=sys.stderr)
            return 1
    else:
        infile = sys.stdin

    if args.output:
        try:
            outfile = open(args.output, "w", encoding="utf-8")
        except OSError as exc:
            print(f"error: cannot open {args.output}: {exc}", file=sys.stderr)
            if infile is not sys.stdin:
                infile.close()
            return 1
    else:
        outfile = sys.stdout

    seen = set()

    try:
        for line in infile:
            key = line_key(line, args.ignore_case)
            if key not in seen:
                seen.add(key)
                outfile.write(line)
    except OSError as exc:
        print(f"error: I/O error: {exc}", file=sys.stderr)
        return 1
    finally:
        if infile is not sys.stdin:
            infile.close()
        if outfile is not sys.stdout:
            outfile.close()

    return 0


if __name__ == "__main__":
    sys.exit(main())
```

Example usage:

```bash
python dedupe.py input.txt
python dedupe.py input.txt --ignore-case
python dedupe.py input.txt --ignore-case -o output.txt
cat input.txt | python dedupe.py --ignore-case
```
